<script setup>
import { computed, ref } from 'vue'
import { useSchoolStore } from '../stores/school'
const school = useSchoolStore()
const query = ref('')
const filterClass = ref('All classes')
const modalOpen = ref(false)
const editingId = ref(null)
const formError = ref('')
const form = ref({ name: '', email: '', className: 'Grade 8', section: 'A', parentEmail: '' })
const filtered = computed(() => school.students.filter(student => (filterClass.value === 'All classes' || student.className === filterClass.value) && `${student.name} ${student.id} ${student.email}`.toLowerCase().includes(query.value.toLowerCase())))
const classes = computed(() => ['All classes', ...new Set(school.students.map(student => student.className))])
function openAdd() { editingId.value = null; form.value = { name: '', email: '', className: 'Grade 8', section: 'A', parentEmail: '' }; formError.value = ''; modalOpen.value = true }
function edit(student) { editingId.value = student.id; form.value = { ...student }; formError.value = ''; modalOpen.value = true }
function save() {
  if (!form.value.name.trim() || !/^\S+@\S+\.\S+$/.test(form.value.email)) { formError.value = 'Enter a student name and valid email.'; return }
  school.saveStudent({ ...form.value, id: editingId.value || `ST-${Math.floor(2407 + Math.random() * 900)}` }); modalOpen.value = false
}
function remove(student) { if (window.confirm(`Delete ${student.name}'s student record?`)) school.deleteStudent(student.id) }
</script>
<template><div class="page-intro"><div><div class="date-label">SCHOOL DIRECTORY</div><h1>Students <span class="count-badge">{{ school.students.length }}</span></h1><p>Manage your student records and keep everyone on track.</p></div><button class="primary-button" @click="openAdd"><span>＋</span> Add student</button></div><section class="panel directory-panel"><div class="directory-toolbar"><div><h2>All students</h2><p>A complete overview of your student body</p></div><div class="table-tools"><label class="search-field"><span>⌕</span><input v-model="query" placeholder="Search students..." /></label><select v-model="filterClass" class="select-pill" aria-label="Filter by class"><option v-for="name in classes" :key="name">{{ name }}</option></select><button class="outline-button export-button" @click="window.print()">↓ Export</button></div></div><div class="table-scroll"><table class="data-table directory-table"><thead><tr><th>STUDENT</th><th>CLASS & SECTION</th><th>EMAIL</th><th>ATTENDANCE</th><th>AVG. SCORE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="student in filtered" :key="student.id"><td><div class="person-cell"><span class="avatar" :class="`avatar-${student.color}`">{{ student.initials }}</span><span><strong>{{ student.name }}</strong><small>{{ student.id }}</small></span></div></td><td>{{ student.className }} · {{ student.section }}</td><td class="email-cell">{{ student.email }}</td><td><span class="attendance-number">{{ student.attendance }}%</span></td><td><strong class="score-number">{{ student.average }}%</strong></td><td><span class="status-pill" :class="student.status === 'Excellent' ? 'status-green' : student.status === 'Needs support' ? 'status-amber' : 'status-blue'">{{ student.status }}</span></td><td><div class="row-actions"><button aria-label="Edit student" @click="edit(student)">✎</button><button aria-label="Delete student" @click="remove(student)">×</button></div></td></tr><tr v-if="!filtered.length"><td colspan="7" class="empty-state">No students match your search.</td></tr></tbody></table></div><div class="table-footer"><span>Showing <strong>{{ filtered.length }}</strong> of <strong>{{ school.students.length }}</strong> students</span><div><button disabled>←</button><button class="current-page">1</button><button disabled>→</button></div></div></section><div v-if="modalOpen" class="modal-backdrop" @click.self="modalOpen = false"><form class="student-modal" @submit.prevent="save"><div class="modal-top"><div><h2>{{ editingId ? 'Edit student' : 'Add a student' }}</h2><p>Student records are stored in this browser demo.</p></div><button type="button" class="modal-close" @click="modalOpen = false">×</button></div><label>Full name<input v-model="form.name" placeholder="e.g. Maya Thompson" /></label><label>Student email<input v-model="form.email" type="email" placeholder="student@mestar.edu" /></label><div class="form-row"><label>Class<select v-model="form.className"><option>Grade 7</option><option>Grade 8</option><option>Grade 9</option></select></label><label>Section<select v-model="form.section"><option>A</option><option>B</option><option>C</option></select></label></div><label>Parent email <small>(optional)</small><input v-model="form.parentEmail" type="email" placeholder="parent@example.com" /></label><p v-if="formError" class="form-error">{{ formError }}</p><div class="modal-actions"><button type="button" class="outline-button" @click="modalOpen = false">Cancel</button><button class="primary-button" type="submit">{{ editingId ? 'Save changes' : 'Add student' }}</button></div></form></div></template>
<script>export default { methods: { window } }</script>
